// TEMA 13 — Delitos contra la libertad sexual (Título VIII del Libro II CP, arts. 178 a 194 bis).
// Formato: o[0] es SIEMPRE la respuesta correcta (la web baraja el orden al mostrarla).
// Verificado contra: Código Penal, BOE-A-1995-25444, texto consolidado (última actualización publicada el 09/04/2026).
// Redacción vigente: LO 10/2022 (en vigor 07/10/2022) y LO 4/2023 (en vigor 29/04/2023).
window.BANCO = window.BANCO || {};
window.BANCO[13] = [
  // --- ESTRUCTURA Y REFORMAS ---
  {id:"T13-001", p:"¿Cómo se denomina el Título VIII del Libro II del Código Penal?", o:["Delitos contra la libertad sexual","Delitos contra la libertad e indemnidad sexuales","Delitos contra la integridad moral","Delitos contra la intimidad y la propia imagen"], e:"Desde la LO 10/2022, el Título VIII se denomina «Delitos contra la libertad sexual».", a:"Título VIII del Libro II CP (arts. 178 a 194 bis)", f:"Texto legal"},
  {id:"T13-002", p:"¿En cuántos capítulos se divide el Título VIII del Libro II del Código Penal?", o:["Seis","Cinco","Siete","Cuatro"], e:"Los seis capítulos son: agresiones sexuales; agresiones sexuales a menores de dieciséis años; acoso sexual; exhibicionismo y provocación sexual; prostitución, explotación sexual y corrupción de menores; y disposiciones comunes.", a:"Título VIII, Capítulos I a VI CP", f:"Texto legal"},
  {id:"T13-003", p:"¿Qué ley orgánica dio la nueva regulación a los delitos contra la libertad sexual y cuándo entró en vigor?", o:["La LO 10/2022, de 6 de septiembre, de garantía integral de la libertad sexual, en vigor el 7 de octubre de 2022","La LO 4/2023, de 27 de abril, en vigor el 29 de abril de 2023","La LO 1/2015, de 30 de marzo, en vigor el 1 de julio de 2015","La LO 8/2021, de 4 de junio, en vigor el 25 de junio de 2021"], e:"La LO 10/2022, de 6 de septiembre, de garantía integral de la libertad sexual, entró en vigor el 7 de octubre de 2022.", a:"LO 10/2022 (Título VIII CP)", f:"Texto legal y temario"},
  {id:"T13-004", p:"¿Cuál es la última ley orgánica que ha modificado el Título VIII del Código Penal y cuándo entró en vigor?", o:["La LO 4/2023, de 27 de abril, en vigor desde el 29 de abril de 2023","La LO 10/2022, de 6 de septiembre, en vigor desde el 7 de octubre de 2022","La LO 14/2022, de 22 de diciembre, en vigor desde el 12 de enero de 2023","La LO 5/2010, de 22 de junio, en vigor desde el 23 de diciembre de 2010"], e:"La LO 4/2023, de 27 de abril (BOE de 28/04/2023), entró en vigor el 29/04/2023. Modificó, entre otros, los arts. 178, 179, 180 y 181. El proyecto de ley de protección de menores en entornos digitales, que cambiaría varios artículos, sigue en tramitación.", a:"LO 4/2023 (arts. 178 a 181 CP)", f:"Texto legal (BOE-A-2023-10213)"},
  {id:"T13-005", p:"¿Cómo se denomina el Capítulo II del Título VIII del Código Penal?", o:["De las agresiones sexuales a menores de dieciséis años","De los abusos sexuales","De los abusos y agresiones sexuales a menores de dieciséis años","De la corrupción de menores"], e:"Tras la LO 10/2022, el Capítulo II se titula «De las agresiones sexuales a menores de dieciséis años» (arts. 181 a 183 bis).", a:"Título VIII, Capítulo II CP", f:"Texto legal"},
  {id:"T13-006", p:"¿Cómo se denomina el Capítulo V del Título VIII del Código Penal?", o:["De los delitos relativos a la prostitución y a la explotación sexual y corrupción de menores","De los delitos de exhibicionismo y provocación sexual","Del acoso sexual","De la trata de seres humanos con fines de explotación sexual"], e:"El Capítulo V (arts. 187 a 189 ter) se titula «De los delitos relativos a la prostitución y a la explotación sexual y corrupción de menores». La trata de seres humanos está en el Título VII bis (art. 177 bis).", a:"Título VIII, Capítulo V CP", f:"Texto legal"},
  {id:"T13-007", p:"¿Qué contiene el Capítulo VI del Título VIII del Código Penal?", o:["Disposiciones comunes a los capítulos anteriores","Los delitos de exhibicionismo y provocación sexual","Los delitos de acoso sexual","Las agresiones sexuales a menores de dieciséis años"], e:"El Capítulo VI (arts. 190 a 194 bis) recoge las «Disposiciones comunes a los capítulos anteriores».", a:"Título VIII, Capítulo VI CP (arts. 190 a 194 bis)", f:"Texto legal"},
  {id:"T13-008", p:"Tras la LO 10/2022, ¿cómo se califica un acto que atenta contra la libertad sexual de otra persona sin su consentimiento, aunque no haya violencia ni intimidación?", o:["Como agresión sexual","Como abuso sexual","Como acoso sexual","Como falta de vejación injusta"], e:"La LO 10/2022 unificó los antiguos abusos y agresiones en un solo tipo de agresión sexual: cualquier acto sin consentimiento es agresión sexual (art. 178.1). El delito de «abuso sexual» ya no existe.", a:"Art. 178.1 CP", f:"Texto legal"},

  // --- ART. 178: AGRESIÓN SEXUAL ---
  {id:"T13-009", p:"Según el artículo 178.1 CP, la agresión sexual básica se castiga con:", o:["Prisión de uno a cuatro años","Prisión de uno a cinco años","Prisión de dos a seis años","Prisión de seis meses a dos años"], e:"Art. 178.1: «Será castigado con la pena de prisión de uno a cuatro años, como responsable de agresión sexual, el que realice cualquier acto que atente contra la libertad sexual de otra persona sin su consentimiento».", a:"Art. 178.1 CP", f:"Texto legal"},
  {id:"T13-010", p:"Según el artículo 178.1 CP, ¿cuándo se entiende que hay consentimiento?", o:["Solo cuando se haya manifestado libremente mediante actos que, en atención a las circunstancias del caso, expresen de manera clara la voluntad de la persona","Cuando la víctima no se oponga de forma expresa","Cuando la víctima lo manifieste por escrito o ante testigos","Cuando no se haya empleado violencia ni intimidación"], e:"Art. 178.1: «Sólo se entenderá que hay consentimiento cuando se haya manifestado libremente mediante actos que, en atención a las circunstancias del caso, expresen de manera clara la voluntad de la persona».", a:"Art. 178.1, segundo párrafo, CP", f:"Texto legal"},
  {id:"T13-011", p:"¿Cuál de las siguientes situaciones NO aparece en el artículo 178.2 CP entre las que se consideran «en todo caso» agresión sexual?", o:["El engaño a la víctima","El empleo de violencia o intimidación","El abuso de una situación de superioridad o de vulnerabilidad de la víctima","Actuar sobre personas privadas de sentido o con la voluntad anulada"], e:"Art. 178.2: violencia, intimidación, abuso de una situación de superioridad o vulnerabilidad, actos sobre personas privadas de sentido o de cuya situación mental se abusare, y actos sobre víctimas con la voluntad anulada. El engaño no está en la lista.", a:"Art. 178.2 CP", f:"Texto legal"},
  {id:"T13-012", p:"Según el artículo 178.3 CP, si la agresión sexual se comete empleando violencia o intimidación, o sobre una víctima con la voluntad anulada, la pena es:", o:["Prisión de uno a cinco años","Prisión de uno a cuatro años","Prisión de dos a ocho años","Prisión de cuatro a doce años"], e:"Art. 178.3: pena de uno a cinco años de prisión.", a:"Art. 178.3 CP", f:"Texto legal"},
  {id:"T13-013", p:"Según el artículo 178.4 CP, el órgano sentenciador, razonándolo en sentencia, puede imponer:", o:["La pena de prisión en su mitad inferior o multa de dieciocho a veinticuatro meses","La pena inferior en grado","La pena de prisión en su mitad inferior o multa de doce a veinticuatro meses","La suspensión de la pena sin condiciones"], e:"Art. 178.4: puede imponer la pena de prisión en su mitad inferior o multa de dieciocho a veinticuatro meses, por la menor entidad del hecho y las circunstancias personales del culpable.", a:"Art. 178.4 CP", f:"Texto legal"},
  {id:"T13-014", p:"¿En qué caso NO puede aplicarse la atenuación del artículo 178.4 CP (mitad inferior o multa)?", o:["Cuando medie violencia o intimidación, la víctima tenga anulada su voluntad o concurran las circunstancias del artículo 180","Cuando el autor no tenga antecedentes penales","Cuando el hecho sea de menor entidad","Cuando la víctima sea mayor de edad"], e:"Art. 178.4: solo se aplica «siempre que no medie violencia o intimidación o que la víctima tuviera anulada por cualquier causa su voluntad o no concurran las circunstancias del artículo 180».", a:"Art. 178.4 CP", f:"Texto legal"},
  {id:"T13-015", p:"Según el artículo 178.4 CP, ¿qué debe valorar el tribunal para atenuar la pena?", o:["La menor entidad del hecho y las circunstancias personales del culpable","El perdón de la víctima","La reparación económica del daño","La confesión del autor antes del juicio"], e:"Art. 178.4: «…en atención a la menor entidad del hecho y a las circunstancias personales del culpable».", a:"Art. 178.4 CP", f:"Texto legal"},
  {id:"T13-016", p:"Según la clasificación del artículo 13 CP, la agresión sexual del artículo 178.1 (prisión de uno a cuatro años) es un delito:", o:["Menos grave","Grave","Leve","Grave o menos grave, según decida el juez"], e:"La prisión de tres meses a cinco años es pena menos grave (art. 33.3). Con uno a cuatro años, el delito es menos grave.", a:"Arts. 13 y 178.1 CP", f:"Texto legal y temario"},
  {id:"T13-017", p:"Realizar un acto de contenido sexual sobre una persona que se encuentra privada de sentido constituye:", o:["En todo caso, agresión sexual (art. 178.2)","Abuso sexual","Agresión sexual solo si hay violencia","Delito de acoso sexual"], e:"El art. 178.2 considera en todo caso agresión sexual los actos que se ejecuten sobre personas que se hallen privadas de sentido.", a:"Art. 178.2 CP", f:"Texto legal"},
  {id:"T13-018", p:"Una persona realiza un tocamiento de contenido sexual a otra sin su consentimiento, sin violencia ni intimidación. ¿Qué precepto se aplica?", o:["El artículo 178.1 CP (agresión sexual, prisión de uno a cuatro años)","El artículo 178.3 CP (prisión de uno a cinco años)","El artículo 184 CP (acoso sexual)","El artículo 185 CP (exhibicionismo)"], e:"Cualquier acto que atente contra la libertad sexual sin consentimiento es agresión sexual del art. 178.1. El 178.3 exige violencia, intimidación o voluntad anulada.", a:"Art. 178.1 CP", f:"Texto legal"},
  {id:"T13-019", p:"Si la agresión sexual sin acceso carnal se comete empleando intimidación, ¿qué apartado del artículo 178 CP se aplica?", o:["El 178.3","El 178.1","El 178.4","El 178.2, que fija su propia pena"], e:"El 178.2 dice qué actos son en todo caso agresión sexual, pero no fija pena. Cuando hay violencia, intimidación o voluntad anulada, la pena es la del 178.3 (uno a cinco años).", a:"Art. 178.2 y 3 CP", f:"Texto legal"},

  // --- ART. 179: VIOLACIÓN ---
  {id:"T13-020", p:"Según el artículo 179.1 CP, ¿cuándo se castiga la agresión sexual como violación?", o:["Cuando consista en acceso carnal por vía vaginal, anal o bucal, o en introducción de miembros corporales u objetos por alguna de las dos primeras vías","Cuando se emplee violencia o intimidación","Cuando la víctima sea menor de dieciséis años","Cuando la cometan dos o más personas"], e:"Art. 179.1: acceso carnal por vía vaginal, anal o bucal, o introducción de miembros corporales u objetos por alguna de las dos primeras vías (vaginal o anal).", a:"Art. 179.1 CP", f:"Texto legal"},
  {id:"T13-021", p:"¿Cuál es la pena de la violación del artículo 179.1 CP?", o:["Prisión de cuatro a doce años","Prisión de seis a doce años","Prisión de uno a cinco años","Prisión de siete a quince años"], e:"Art. 179.1: «…será castigado como reo de violación con la pena de prisión de cuatro a doce años».", a:"Art. 179.1 CP", f:"Texto legal"},
  {id:"T13-022", p:"Según el artículo 179.2 CP, si la violación se comete empleando violencia o intimidación, o la víctima tiene anulada su voluntad, la pena es:", o:["Prisión de seis a doce años","Prisión de cuatro a doce años","Prisión de doce a quince años","Prisión de siete a quince años"], e:"Art. 179.2: pena de prisión de seis a doce años. Este apartado lo introdujo la LO 4/2023.", a:"Art. 179.2 CP", f:"Texto legal"},
  {id:"T13-023", p:"La introducción de objetos por vía bucal, sin acceso carnal, ¿constituye violación del artículo 179.1 CP?", o:["No, porque el 179.1 solo contempla la introducción de miembros corporales u objetos por las vías vaginal o anal; sería agresión sexual del 178","Sí, porque el 179.1 incluye las tres vías para cualquier introducción","Sí, si se emplea violencia","No, porque sería un delito de lesiones"], e:"El art. 179.1 incluye el acceso carnal por las tres vías (vaginal, anal o bucal), pero la introducción de miembros corporales u objetos solo «por alguna de las dos primeras vías» (vaginal o anal).", a:"Art. 179.1 CP", f:"Texto legal"},
  {id:"T13-024", p:"¿Qué ley orgánica añadió al artículo 179 CP el apartado 2 (seis a doce años con violencia, intimidación o voluntad anulada)?", o:["La LO 4/2023, de 27 de abril","La LO 10/2022, de 6 de septiembre","La LO 1/2015, de 30 de marzo","La LO 5/2010, de 22 de junio"], e:"La LO 4/2023 modificó el art. 179 para corregir los efectos no deseados de la LO 10/2022, añadiendo el tipo agravado con violencia, intimidación o voluntad anulada.", a:"Art. 179.2 CP (redacción LO 4/2023)", f:"Texto legal (BOE-A-2023-10213)"},
  {id:"T13-025", p:"La violación del artículo 179.1 CP (prisión de cuatro a doce años), según el artículo 13 CP, es un delito:", o:["Grave","Menos grave","Leve","Menos grave, si no hay violencia"], e:"La prisión de más de cinco años es pena grave. Una pena de cuatro a doce años abarca las dos categorías y, según el art. 13.4, el delito se considera grave.", a:"Arts. 13 y 179.1 CP", f:"Texto legal y temario"},

  // --- ART. 180: AGRAVANTES ---
  {id:"T13-026", p:"Según el artículo 180.1 CP, si concurre alguna de sus circunstancias agravantes, la agresión del artículo 178.1 se castiga con:", o:["Prisión de dos a ocho años","Prisión de cinco a diez años","Prisión de uno a cinco años","Prisión de siete a quince años"], e:"Art. 180.1: dos a ocho años para el 178.1; cinco a diez para el 178.3; siete a quince para el 179.1; y doce a quince para el 179.2.", a:"Art. 180.1 CP", f:"Texto legal"},
  {id:"T13-027", p:"Si concurre alguna circunstancia del artículo 180.1 CP en una agresión sexual del artículo 178.3 (con violencia o intimidación), la pena es:", o:["Prisión de cinco a diez años","Prisión de dos a ocho años","Prisión de siete a quince años","Prisión de doce a quince años"], e:"Art. 180.1: prisión de cinco a diez años para las agresiones del art. 178.3.", a:"Art. 180.1 CP", f:"Texto legal"},
  {id:"T13-028", p:"Si concurre alguna circunstancia del artículo 180.1 CP en una violación del artículo 179.1, la pena es:", o:["Prisión de siete a quince años","Prisión de doce a quince años","Prisión de cinco a diez años","Prisión de seis a doce años"], e:"Art. 180.1: prisión de siete a quince años para las agresiones del art. 179.1.", a:"Art. 180.1 CP", f:"Texto legal"},
  {id:"T13-029", p:"Si concurre alguna circunstancia del artículo 180.1 CP en una violación con violencia o intimidación (179.2), la pena es:", o:["Prisión de doce a quince años","Prisión de siete a quince años","Prisión de seis a doce años","Prisión de ocho a doce años"], e:"Art. 180.1: prisión de doce a quince años para las agresiones del art. 179.2.", a:"Art. 180.1 CP", f:"Texto legal"},
  {id:"T13-030", p:"¿Cuál es la primera circunstancia agravante del artículo 180.1 CP?", o:["Que los hechos se cometan por la actuación conjunta de dos o más personas","Que el autor haga uso de armas","Que la víctima sea menor de edad","Que el autor sea reincidente"], e:"Art. 180.1.1.ª: «Cuando los hechos se cometan por la actuación conjunta de dos o más personas».", a:"Art. 180.1.1.ª CP", f:"Texto legal"},
  {id:"T13-031", p:"Según el artículo 180.1.4.ª CP, se agrava la agresión sexual cuando la víctima:", o:["Sea o haya sido esposa o mujer que esté o haya estado ligada al autor por análoga relación de afectividad, aun sin convivencia","Sea pareja actual del autor, siempre que convivan","Sea familiar del autor hasta el segundo grado","Sea compañera de trabajo del autor"], e:"Art. 180.1.4.ª: cuando la víctima sea o haya sido esposa o mujer que esté o haya estado ligada por análoga relación de afectividad, aun sin convivencia.", a:"Art. 180.1.4.ª CP", f:"Texto legal"},
  {id:"T13-032", p:"Según el artículo 180.1.6.ª CP, se agrava la agresión sexual cuando el responsable haga uso de armas u otros medios igualmente peligrosos susceptibles de producir la muerte o las lesiones de los artículos:", o:["149 y 150","147 y 148","148 y 149","150 y 151"], e:"Art. 180.1.6.ª: «…susceptibles de producir la muerte o alguna de las lesiones previstas en los artículos 149 y 150…, sin perjuicio de lo dispuesto en el artículo 194 bis».", a:"Art. 180.1.6.ª CP", f:"Texto legal"},
  {id:"T13-033", p:"¿Qué circunstancia del artículo 180.1 CP se aplica cuando el autor anula la voluntad de la víctima suministrándole fármacos, drogas u otras sustancias?", o:["La 7.ª","La 2.ª","La 3.ª","La 5.ª"], e:"Art. 180.1.7.ª: cuando la persona responsable haya anulado la voluntad de la víctima suministrándole fármacos, drogas o cualquier otra sustancia natural o química idónea a tal efecto (la llamada «sumisión química»).", a:"Art. 180.1.7.ª CP", f:"Texto legal"},
  {id:"T13-034", p:"Según el artículo 180.2 CP, si concurren dos o más de las circunstancias del apartado 1:", o:["Las penas se impondrán en su mitad superior","Se impondrá la pena superior en grado","Se sumarán las penas de cada circunstancia","Se aplicará la pena máxima"], e:"Art. 180.2: «Si concurrieren dos o más de las anteriores circunstancias, las penas respectivamente previstas en el apartado 1 de este artículo se impondrán en su mitad superior».", a:"Art. 180.2 CP", f:"Texto legal"},
  {id:"T13-035", p:"Según el artículo 180.3 CP, si el culpable de una agresión sexual se ha prevalido de su condición de autoridad, agente de esta o funcionario público, se impondrá además:", o:["Inhabilitación absoluta de seis a doce años","Inhabilitación especial de dos a seis años","Inhabilitación absoluta de dos a cinco años","Suspensión de empleo de tres a seis años"], e:"Art. 180.3: en todos los casos del capítulo, «se impondrá, además, la pena de inhabilitación absoluta de seis a doce años».", a:"Art. 180.3 CP", f:"Texto legal"},
  {id:"T13-036", p:"Según el artículo 180.1 CP, cuando en la descripción del tipo de los artículos 178 o 179 ya se haya tenido en cuenta alguna de sus circunstancias, el conflicto se resolverá:", o:["Conforme a la regla del artículo 8.4 CP","Aplicando siempre la circunstancia agravante","Conforme a la regla del artículo 77 CP (concurso ideal)","Mediante la pena inferior en grado"], e:"Art. 180.1, párrafo final: el conflicto se resolverá conforme al art. 8.4 CP, según el cual el precepto penal más grave excluye los que castigan el hecho con pena menor.", a:"Art. 180.1, último párrafo, y art. 8.4 CP", f:"Texto legal"},
  {id:"T13-037", p:"La circunstancia 3.ª del artículo 180.1 CP (víctima en situación de especial vulnerabilidad por edad, enfermedad, discapacidad u otra circunstancia) se aplica:", o:["Salvo lo dispuesto en el artículo 181","Solo si la víctima es mayor de 65 años","Solo si la discapacidad está reconocida administrativamente","En todo caso, también a las víctimas menores de dieciséis años"], e:"Art. 180.1.3.ª: «…salvo lo dispuesto en el artículo 181». Las agresiones a menores de dieciséis años tienen su propio régimen en el art. 181.", a:"Art. 180.1.3.ª CP", f:"Texto legal"},
  {id:"T13-038", p:"Según el artículo 180.1.5.ª CP, se agrava la agresión sexual cuando el responsable:", o:["Se haya prevalido de una situación o relación de convivencia, de parentesco o de superioridad con respecto a la víctima","Sea reincidente en delitos de la misma naturaleza","Actúe con ánimo de lucro","Grabe los hechos"], e:"Art. 180.1.5.ª: cuando el responsable se hubiera prevalido de una situación o relación de convivencia o de parentesco o de una relación de superioridad con respecto a la víctima.", a:"Art. 180.1.5.ª CP", f:"Texto legal"},

  // --- ART. 181: MENORES DE DIECISÉIS AÑOS ---
  {id:"T13-039", p:"Según el artículo 181.1 CP, quien realice actos de carácter sexual con un menor de dieciséis años será castigado con:", o:["Prisión de dos a seis años","Prisión de uno a cuatro años","Prisión de cinco a diez años","Prisión de dos a seis años, previa denuncia del representante legal"], e:"Art. 181.1: «El que realizare actos de carácter sexual con un menor de dieciséis años, será castigado con la pena de prisión de dos a seis años». No exige denuncia previa.", a:"Art. 181.1 CP", f:"Texto legal"},
  {id:"T13-040", p:"A efectos del artículo 181.1 CP, ¿se consideran incluidos los actos que el menor realice con un tercero o sobre sí mismo a instancia del autor?", o:["Sí, se consideran incluidos","No, solo los actos que realice el propio autor sobre el menor","Solo si el autor está presente físicamente","Solo si el menor tiene menos de trece años"], e:"Art. 181.1, segundo párrafo: «A estos efectos se consideran incluidos en los actos de carácter sexual los que realice el menor con un tercero o sobre sí mismo a instancia del autor».", a:"Art. 181.1, párrafo segundo, CP", f:"Texto legal"},
  {id:"T13-041", p:"Según el artículo 181.2 CP, si en los actos sexuales con un menor de dieciséis años concurre alguna de las modalidades del artículo 178.2 y 3, la pena es:", o:["Prisión de cinco a diez años","Prisión de dos a seis años","Prisión de ocho a doce años","Prisión de doce a quince años"], e:"Art. 181.2: se impondrá una pena de prisión de cinco a diez años.", a:"Art. 181.2 CP", f:"Texto legal"},
  {id:"T13-042", p:"Según el artículo 181.3 CP, el órgano sentenciador puede imponer la pena de prisión inferior en grado, EXCEPTO:", o:["Cuando medie violencia o intimidación, la víctima tenga anulada su voluntad o concurran las circunstancias del apartado 5","Cuando el autor sea menor de edad","Cuando el menor haya consentido","Cuando el hecho sea de menor entidad"], e:"Art. 181.3: la pena inferior en grado no se aplica cuando medie violencia o intimidación, la víctima tenga anulada su voluntad o concurran las circunstancias del art. 181.5.", a:"Art. 181.3 CP", f:"Texto legal"},
  {id:"T13-043", p:"Según el artículo 181.4 CP, cuando el acto sexual con un menor de dieciséis años consista en acceso carnal (o introducción de miembros corporales u objetos por vía vaginal o anal), la pena en los casos del apartado 1 es:", o:["Prisión de ocho a doce años","Prisión de doce a quince años","Prisión de cuatro a doce años","Prisión de seis a doce años"], e:"Art. 181.4: ocho a doce años en los casos del apartado 1 y doce a quince años en los del apartado 2.", a:"Art. 181.4 CP", f:"Texto legal"},
  {id:"T13-044", p:"Según el artículo 181.4 CP, en los casos de acceso carnal con un menor de dieciséis años en los que concurran las modalidades del artículo 178.2 y 3 (apartado 2), la pena es:", o:["Prisión de doce a quince años","Prisión de ocho a doce años","Prisión de cinco a diez años","Prisión de siete a quince años"], e:"Art. 181.4: prisión de doce a quince años en los casos del apartado 2.", a:"Art. 181.4 CP", f:"Texto legal"},
  {id:"T13-045", p:"Según el artículo 181.5 CP, cuando concurra alguna de sus circunstancias agravantes, las conductas de los apartados anteriores se castigan con:", o:["La pena de prisión correspondiente en su mitad superior","La pena superior en grado","La pena de prisión de doce a quince años","La pena correspondiente más una multa de doce a veinticuatro meses"], e:"Art. 181.5: «…serán castigadas con la pena de prisión correspondiente en su mitad superior cuando concurra alguna de las siguientes circunstancias».", a:"Art. 181.5 CP", f:"Texto legal"},
  {id:"T13-046", p:"Según el artículo 181.5.c) CP, la circunstancia de especial vulnerabilidad de la víctima concurre en todo caso cuando esta sea menor de:", o:["Cuatro años","Siete años","Doce años","Trece años"], e:"Art. 181.5.c): «…y, en todo caso, cuando sea menor de cuatro años».", a:"Art. 181.5.c) CP", f:"Texto legal"},
  {id:"T13-047", p:"¿En qué se diferencia la agravante del artículo 181.5.d) (menores) de la del artículo 180.1.4.ª (adultos) respecto a la relación con el autor?", o:["El 181.5.d) se refiere a que la víctima sea o haya sido pareja del autor; el 180.1.4.ª, a que sea o haya sido esposa o mujer ligada por análoga relación de afectividad","Son idénticas","El 181.5.d) exige convivencia y el 180.1.4.ª no","El 181.5.d) solo se aplica a víctimas varones"], e:"Art. 181.5.d): «Cuando la víctima sea o haya sido pareja del autor, aun sin convivencia». Art. 180.1.4.ª: «…esposa o mujer que esté o haya estado ligada por análoga relación de afectividad, aun sin convivencia».", a:"Arts. 180.1.4.ª y 181.5.d) CP", f:"Texto legal"},
  {id:"T13-048", p:"¿Qué circunstancia agravante figura en el artículo 181.5 CP (menores de dieciséis años) pero NO en el artículo 180.1 CP?", o:["Que la infracción se cometa en el seno de una organización o grupo criminal dedicado a esas actividades","La actuación conjunta de dos o más personas","El uso de armas u otros medios peligrosos","La anulación de la voluntad de la víctima con fármacos o drogas"], e:"El art. 181.5.h) añade la comisión en el seno de una organización o grupo criminal dedicado a estas actividades. Las otras tres están en ambos artículos.", a:"Art. 181.5.h) CP", f:"Texto legal"},
  {id:"T13-049", p:"Según el artículo 181.6 CP, si concurren dos o más de las circunstancias del apartado 5:", o:["Las penas del apartado anterior se impondrán en su mitad superior","Se impondrá la pena superior en grado","Se impondrá la pena máxima de quince años","Se aplicará el concurso real"], e:"Art. 181.6: «Si concurrieren dos o más de las anteriores circunstancias, las penas del apartado anterior se impondrán en su mitad superior».", a:"Art. 181.6 CP", f:"Texto legal"},
  {id:"T13-050", p:"Según el artículo 181.7 CP, si el culpable se ha prevalido de su condición de autoridad, agente de esta o funcionario público, se le impondrá además:", o:["Inhabilitación absoluta de seis a doce años","Inhabilitación especial de seis a doce años","Inhabilitación absoluta de cuatro a diez años","Privación de la patria potestad"], e:"Art. 181.7: «…se impondrá, además, la pena de inhabilitación absoluta de seis a doce años».", a:"Art. 181.7 CP", f:"Texto legal"},
  {id:"T13-051", p:"El funcionario de un centro de protección de menores solicita sexualmente a una menor de 14 años sujeta a su guarda, sin que conste ningún otro acto. ¿Cómo se califican los hechos?", o:["Como delito del artículo 443.2 CP (funcionario de centro de protección que solicita sexualmente a persona sujeta a su guarda)","Como agresión sexual a menor de dieciséis años del artículo 181.1 CP, agravada por especial vulnerabilidad","Como ambos delitos en concurso real, según el artículo 444 CP","Como delito de exhibicionismo del artículo 185 CP"], e:"Solicitar no es «realizar actos de carácter sexual», así que no hay delito del 181. El art. 443.2 castiga al funcionario de centros de protección que solicita sexualmente a una persona sujeta a su guarda (prisión de uno a cuatro años e inhabilitación absoluta de seis a doce). El art. 444 solo añade pena por los delitos sexuales efectivamente cometidos, que aquí no constan.", a:"Arts. 443.2 y 444 CP", f:"Texto legal"},

  // --- ART. 182 ---
  {id:"T13-052", p:"Según el artículo 182.1 CP, quien con fines sexuales haga presenciar a un menor de dieciséis años actos de carácter sexual, aunque no participe en ellos, será castigado con:", o:["Prisión de seis meses a dos años","Prisión de uno a tres años","Prisión de dos a seis años","Prisión de seis meses a un año o multa de doce a veinticuatro meses"], e:"Art. 182.1: pena de prisión de seis meses a dos años.", a:"Art. 182.1 CP", f:"Texto legal"},
  {id:"T13-053", p:"Según el artículo 182.2 CP, si los actos de carácter sexual que se hacen presenciar al menor de dieciséis años constituyen un delito contra la libertad sexual, la pena es:", o:["Prisión de uno a tres años","Prisión de seis meses a dos años","Prisión de dos a seis años","Prisión de tres a cinco años"], e:"Art. 182.2: «…la pena será de prisión de uno a tres años».", a:"Art. 182.2 CP", f:"Texto legal"},

  // --- ART. 183 ---
  {id:"T13-054", p:"Según el artículo 183.1 CP, quien a través de internet, teléfono u otra tecnología contacte con un menor de dieciséis años y le proponga un encuentro para cometer delitos de los artículos 181 y 189, acompañando la propuesta de actos materiales de acercamiento, será castigado con:", o:["Prisión de uno a tres años o multa de doce a veinticuatro meses","Prisión de seis meses a dos años","Prisión de dos a seis años","Prisión de uno a cinco años"], e:"Art. 183.1: pena de uno a tres años de prisión o multa de doce a veinticuatro meses, sin perjuicio de las penas de los delitos que en su caso se cometan.", a:"Art. 183.1 CP", f:"Texto legal"},
  {id:"T13-055", p:"¿Qué requisito exige el artículo 183.1 CP, además del contacto y de la propuesta de encuentro con el menor de dieciséis años?", o:["Que la propuesta se acompañe de actos materiales encaminados al acercamiento","Que el encuentro llegue a producirse","Que el menor acepte la propuesta","Que el autor sea mayor de edad"], e:"Art. 183.1: «…siempre que tal propuesta se acompañe de actos materiales encaminados al acercamiento».", a:"Art. 183.1 CP", f:"Texto legal"},
  {id:"T13-056", p:"Según el artículo 183.1 CP, las penas se impondrán en su mitad superior cuando el acercamiento se obtenga mediante:", o:["Coacción, intimidación o engaño","Violencia física","Regalos o promesas","Suplantación de identidad, en todo caso"], e:"Art. 183.1: «Las penas se impondrán en su mitad superior cuando el acercamiento se obtenga mediante coacción, intimidación o engaño».", a:"Art. 183.1 CP", f:"Texto legal"},
  {id:"T13-057", p:"Según el artículo 183.2 CP, quien a través de tecnologías de la información contacte con un menor de dieciséis años y realice actos dirigidos a embaucarle para que le facilite material pornográfico o le muestre imágenes pornográficas en las que aparezca un menor, será castigado con:", o:["Prisión de seis meses a dos años","Prisión de uno a tres años o multa de doce a veinticuatro meses","Prisión de uno a cinco años","Multa de seis a doce meses"], e:"Art. 183.2: pena de prisión de seis meses a dos años.", a:"Art. 183.2 CP", f:"Texto legal"},
  {id:"T13-058", p:"El delito del artículo 183.1 CP se refiere a proponer un encuentro con el menor «a fin de cometer cualquiera de los delitos descritos en los artículos»:", o:["181 y 189","178 y 179","182 y 185","187 y 188"], e:"Art. 183.1: «…a fin de cometer cualquiera de los delitos descritos en los artículos 181 y 189…».", a:"Art. 183.1 CP", f:"Texto legal"},

  // --- ART. 183 BIS ---
  {id:"T13-059", p:"Según el artículo 183 bis CP, el libre consentimiento del menor de dieciséis años excluye la responsabilidad penal por los delitos del Capítulo II cuando:", o:["El autor sea una persona próxima al menor por edad y grado de desarrollo o madurez física y psicológica","El menor tenga más de trece años","Los padres del menor lo autoricen","No haya existido acceso carnal"], e:"Art. 183 bis: el libre consentimiento excluye la responsabilidad «cuando el autor sea una persona próxima al menor por edad y grado de desarrollo o madurez física y psicológica».", a:"Art. 183 bis CP", f:"Texto legal"},
  {id:"T13-060", p:"¿En qué caso NO opera la exclusión de responsabilidad del artículo 183 bis CP, aunque el autor sea próximo al menor por edad y madurez?", o:["Cuando concurra alguna de las circunstancias del apartado segundo del artículo 178","Cuando el menor tenga quince años","Cuando el autor sea mayor de edad","Cuando los hechos ocurran en el domicilio del menor"], e:"Art. 183 bis: «Salvo en los casos en que concurra alguna de las circunstancias previstas en el apartado segundo del artículo 178…» (violencia, intimidación, abuso de superioridad o vulnerabilidad, etc.).", a:"Art. 183 bis CP", f:"Texto legal"},
  {id:"T13-061", p:"¿Cuál es la edad de consentimiento sexual que se deriva de los artículos 181 y 183 bis del Código Penal?", o:["16 años","14 años","13 años","18 años"], e:"El art. 181 castiga los actos de carácter sexual con menores de dieciséis años, y el 183 bis solo excluye la responsabilidad cuando el autor es próximo al menor por edad y madurez. La edad de consentimiento es, por tanto, 16 años.", a:"Arts. 181.1 y 183 bis CP", f:"Texto legal y temario"},

  // --- ART. 184: ACOSO SEXUAL ---
  {id:"T13-062", p:"Según el artículo 184.1 CP, ¿qué elementos configuran el delito de acoso sexual?", o:["Solicitar favores de naturaleza sexual, para sí o para un tercero, en una relación laboral, docente, de prestación de servicios o análoga, continuada o habitual, provocando a la víctima una situación objetiva y gravemente intimidatoria, hostil o humillante","Realizar tocamientos de contenido sexual en el lugar de trabajo","Enviar mensajes de contenido sexual a un compañero, aunque sea una sola vez","Solicitar favores sexuales a cualquier persona, en cualquier ámbito"], e:"Art. 184.1: requiere solicitar favores sexuales (para sí o para un tercero), en una relación laboral, docente, de prestación de servicios o análoga, continuada o habitual, y provocar con ello una situación objetiva y gravemente intimidatoria, hostil o humillante.", a:"Art. 184.1 CP", f:"Texto legal"},
  {id:"T13-063", p:"¿Cuál es la pena del acoso sexual básico del artículo 184.1 CP?", o:["Prisión de seis a doce meses o multa de diez a quince meses, e inhabilitación especial para la profesión, oficio o actividad de doce a quince meses","Prisión de uno a dos años e inhabilitación especial de dieciocho a veinticuatro meses","Prisión de tres a seis meses o multa de seis a doce meses","Prisión de seis meses a un año o multa de doce a veinticuatro meses"], e:"Art. 184.1: prisión de seis a doce meses o multa de diez a quince meses e inhabilitación especial para el ejercicio de la profesión, oficio o actividad de doce a quince meses.", a:"Art. 184.1 CP", f:"Texto legal"},
  {id:"T13-064", p:"Según el artículo 184.2 CP, si el acosador se prevale de una situación de superioridad laboral, docente o jerárquica, la pena es:", o:["Prisión de uno a dos años e inhabilitación especial de dieciocho a veinticuatro meses","Prisión de seis a doce meses e inhabilitación especial de doce a quince meses","Prisión de dos a cuatro años","Prisión de uno a tres años o multa de doce a veinticuatro meses"], e:"Art. 184.2: prisión de uno a dos años e inhabilitación especial para el ejercicio de la profesión, oficio o actividad de dieciocho a veinticuatro meses.", a:"Art. 184.2 CP", f:"Texto legal"},
  {id:"T13-065", p:"¿Cuál de los siguientes supuestos NO agrava el acoso sexual según el artículo 184.2 CP?", o:["Que el acosador sea compañero de trabajo de la misma categoría, sin superioridad","Prevalerse de una situación de superioridad laboral, docente o jerárquica","Actuar sobre persona sujeta a su guarda o custodia","Anunciar expresa o tácitamente a la víctima un mal relacionado con sus legítimas expectativas en esa relación"], e:"El art. 184.2 agrava el acoso cuando hay superioridad laboral, docente o jerárquica, cuando la víctima está bajo guarda o custodia del autor, o cuando se anuncia un mal relacionado con sus legítimas expectativas. El compañero sin superioridad cae en el 184.1.", a:"Art. 184.2 CP", f:"Texto legal"},
  {id:"T13-066", p:"Según el artículo 184.3 CP, el acoso sexual cometido en centros de protección o reforma de menores, centros de internamiento de extranjeros o cualquier otro centro de detención, custodia o acogida, se castiga con:", o:["Prisión de uno a dos años e inhabilitación especial de dieciocho a veinticuatro meses, sin perjuicio del artículo 443.2","Prisión de dos a cuatro años","Prisión de seis a doce meses o multa de diez a quince meses","Prisión de uno a cuatro años e inhabilitación absoluta de seis a doce años"], e:"Art. 184.3: prisión de uno a dos años e inhabilitación especial de dieciocho a veinticuatro meses, «sin perjuicio de lo establecido en el artículo 443.2».", a:"Art. 184.3 CP", f:"Texto legal"},
  {id:"T13-067", p:"Según el artículo 184.4 CP, cuando la víctima del acoso sexual se halle en situación de especial vulnerabilidad por razón de su edad, enfermedad o discapacidad:", o:["La pena se impondrá en su mitad superior","Se impondrá la pena superior en grado","Se impondrá la pena de inhabilitación absoluta","Se aplicará el artículo 178"], e:"Art. 184.4: «…la pena se impondrá en su mitad superior».", a:"Art. 184.4 CP", f:"Texto legal"},
  {id:"T13-068", p:"Según el artículo 184.5 CP, si una persona jurídica es responsable del delito de acoso sexual, se le impondrá:", o:["Multa de seis meses a dos años, y además podrán imponerse las penas de las letras b) a g) del artículo 33.7","Multa del triple al quíntuple del beneficio obtenido","Disolución en todo caso","Multa de doce a veinticuatro meses"], e:"Art. 184.5: pena de multa de seis meses a dos años; atendidas las reglas del art. 66 bis, también pueden imponerse las penas del art. 33.7 b) a g).", a:"Art. 184.5 CP", f:"Texto legal"},
  {id:"T13-069", p:"Según el artículo 184.1 CP, los favores de naturaleza sexual que solicita el acosador pueden ser:", o:["Para sí o para un tercero","Solo para sí mismo","Solo para un superior jerárquico","Solo a cambio de dinero"], e:"Art. 184.1: «El que solicitare favores de naturaleza sexual, para sí o para un tercero…».", a:"Art. 184.1 CP", f:"Texto legal"},

  // --- ARTS. 185 Y 186 ---
  {id:"T13-070", p:"¿Qué delito comete quien ejecuta o hace ejecutar a otra persona actos de exhibición obscena ante menores de edad o personas con discapacidad necesitadas de especial protección?", o:["Exhibicionismo (art. 185 CP)","Provocación sexual (art. 186 CP)","Acoso sexual (art. 184 CP)","Agresión sexual (art. 178 CP)"], e:"Es el delito de exhibicionismo del art. 185 CP. La provocación sexual del art. 186 consiste en vender, difundir o exhibir material pornográfico entre menores o personas con discapacidad.", a:"Art. 185 CP", f:"Examen oficial: Ayto. de València, «Examen B», preg. 16 (fecha no indicada en el documento; sin plantilla; respuesta comprobada con el CP)"},
  {id:"T13-071", p:"¿Cuál es la pena del delito de exhibicionismo del artículo 185 CP?", o:["Prisión de seis meses a un año o multa de 12 a 24 meses","Prisión de seis meses a dos años","Prisión de tres a seis meses o multa de seis a doce meses","Multa de seis a doce meses"], e:"Art. 185: prisión de seis meses a un año o multa de 12 a 24 meses. El art. 186 tiene la misma pena.", a:"Art. 185 CP", f:"Texto legal"},
  {id:"T13-072", p:"Según el artículo 186 CP, comete delito quien, por cualquier medio directo:", o:["Vende, difunde o exhibe material pornográfico entre menores de edad o personas con discapacidad necesitadas de especial protección","Produce material pornográfico con adultos","Ejecuta actos de exhibición obscena ante adultos","Difunde material pornográfico entre adultos sin su consentimiento"], e:"Art. 186: «El que, por cualquier medio directo, vendiere, difundiere o exhibiere material pornográfico entre menores de edad o personas con discapacidad necesitadas de especial protección…». Pena: prisión de seis meses a un año o multa de 12 a 24 meses.", a:"Art. 186 CP", f:"Texto legal"},
  {id:"T13-073", p:"Los actos de exhibición obscena realizados ante personas adultas sin discapacidad, ¿constituyen el delito del artículo 185 CP?", o:["No, el artículo 185 solo protege a menores de edad y a personas con discapacidad necesitadas de especial protección","Sí, siempre","Sí, si se realizan en la vía pública","Sí, si la víctima lo denuncia"], e:"El art. 185 exige que la exhibición se realice «ante menores de edad o personas con discapacidad necesitadas de especial protección».", a:"Art. 185 CP", f:"Texto legal"},

  // --- ART. 187: PROSTITUCIÓN DE MAYORES ---
  {id:"T13-074", p:"Según el artículo 187.1 CP, quien empleando violencia, intimidación o engaño, o abusando de una situación de superioridad o de necesidad o vulnerabilidad, determine a una persona mayor de edad a ejercer o mantenerse en la prostitución, será castigado con:", o:["Prisión de dos a cinco años y multa de doce a veinticuatro meses","Prisión de dos a cuatro años y multa de doce a veinticuatro meses","Prisión de uno a cinco años","Prisión de cuatro a ocho años y multa de doce a veinticuatro meses"], e:"Art. 187.1, primer párrafo: prisión de dos a cinco años y multa de doce a veinticuatro meses.", a:"Art. 187.1, párrafo primero, CP", f:"Texto legal"},
  {id:"T13-075", p:"Según el artículo 187.1 CP, quien se lucre explotando la prostitución de otra persona, aun con el consentimiento de esta, será castigado con:", o:["Prisión de dos a cuatro años y multa de doce a veinticuatro meses","Prisión de dos a cinco años y multa de doce a veinticuatro meses","No es delito si hay consentimiento","Multa de seis a doce meses"], e:"Art. 187.1, segundo párrafo: prisión de dos a cuatro años y multa de doce a veinticuatro meses, «aun con el consentimiento de la misma».", a:"Art. 187.1, párrafo segundo, CP", f:"Texto legal"},
  {id:"T13-076", p:"Según el artículo 187.1 CP, se entiende en todo caso que hay explotación de la prostitución cuando:", o:["La víctima esté en una situación de vulnerabilidad personal o económica, o se le impongan condiciones gravosas, desproporcionadas o abusivas","La víctima ejerza la prostitución en un local","El explotador obtenga más del 50 % de los ingresos","La víctima sea extranjera"], e:"Art. 187.1: a) que la víctima se encuentre en una situación de vulnerabilidad personal o económica; b) que se le impongan para su ejercicio condiciones gravosas, desproporcionadas o abusivas.", a:"Art. 187.1 a) y b) CP", f:"Texto legal"},
  {id:"T13-077", p:"¿Cuál de las siguientes circunstancias NO aparece en el artículo 187.2 CP para imponer las penas en su mitad superior?", o:["Que la víctima sea extranjera en situación irregular","Que el culpable se haya prevalido de su condición de autoridad, agente de esta o funcionario público","Que el culpable pertenezca a una organización o grupo criminal dedicado a estas actividades","Que el culpable haya puesto en peligro, dolosamente o por imprudencia grave, la vida o salud de la víctima"], e:"El art. 187.2 recoge tres circunstancias: a) prevalerse de la condición de autoridad (con inhabilitación absoluta de seis a doce años); b) pertenecer a una organización o grupo criminal; c) poner en peligro la vida o salud de la víctima.", a:"Art. 187.2 CP", f:"Texto legal"},
  {id:"T13-078", p:"Según el artículo 187.3 CP, las penas por prostitución coactiva o explotación:", o:["Se impondrán sin perjuicio de las que correspondan por las agresiones o abusos sexuales cometidos sobre la persona prostituida","Absorben las de las agresiones sexuales cometidas","Se reducen si la víctima consintió","Solo se imponen si no hay agresión sexual"], e:"Art. 187.3: «Las penas señaladas se impondrán en sus respectivos casos sin perjuicio de las que correspondan por las agresiones o abusos sexuales cometidos sobre la persona prostituida».", a:"Art. 187.3 CP", f:"Texto legal"},

  // --- ART. 188: PROSTITUCIÓN DE MENORES ---
  {id:"T13-079", p:"Según el artículo 188.1 CP, quien induzca, promueva, favorezca o facilite la prostitución de un menor de edad o persona con discapacidad necesitada de especial protección será castigado con prisión de dos a cinco años y multa. Si la víctima es menor de dieciséis años, la pena de prisión es de:", o:["Cuatro a ocho años","Cinco a diez años","Dos a seis años","Tres a seis años"], e:"Art. 188.1: prisión de dos a cinco años y multa de doce a veinticuatro meses; si la víctima es menor de dieciséis años, prisión de cuatro a ocho años y multa de doce a veinticuatro meses.", a:"Art. 188.1 CP", f:"Texto legal"},
  {id:"T13-080", p:"Según el artículo 188.2 CP, si los hechos del apartado 1 se cometen con violencia o intimidación, la pena de prisión es:", o:["De cinco a diez años si la víctima es menor de dieciséis años y de cuatro a seis años en los demás casos","De cuatro a ocho años en todos los casos","De ocho a doce años si es menor de dieciséis años y de cinco a diez en los demás","La superior en grado en todo caso"], e:"Art. 188.2: además de las multas, prisión de cinco a diez años si la víctima es menor de dieciséis años, y de cuatro a seis años en los demás casos.", a:"Art. 188.2 CP", f:"Texto legal"},
  {id:"T13-081", p:"Según el artículo 188.3 CP, cuando concurran circunstancias como la especial vulnerabilidad de la víctima, el prevalimiento de parentesco o la actuación conjunta de dos o más personas, se impondrán:", o:["Las penas superiores en grado","Las penas en su mitad superior","Las penas en su mitad inferior","Las mismas penas más inhabilitación especial"], e:"Art. 188.3: «Se impondrán las penas superiores en grado a las previstas en los apartados anteriores…». Cuidado: en el 187.2 la consecuencia es la mitad superior, no el grado superior.", a:"Art. 188.3 CP", f:"Texto legal"},
  {id:"T13-082", p:"Según el artículo 188.4 CP, quien solicite, acepte u obtenga, a cambio de remuneración o promesa, una relación sexual con una persona menor de edad será castigado con:", o:["Prisión de uno a cuatro años; si el menor no ha cumplido dieciséis años, de dos a seis años","Prisión de dos a cinco años en todo caso","Prisión de seis meses a dos años","Multa de doce a veinticuatro meses"], e:"Art. 188.4: prisión de uno a cuatro años; de dos a seis años si el menor no hubiera cumplido dieciséis años.", a:"Art. 188.4 CP", f:"Texto legal"},
  {id:"T13-083", p:"Según el artículo 188.5 CP, las penas de este artículo se impondrán:", o:["Sin perjuicio de las que correspondan por las infracciones contra la libertad o indemnidad sexual cometidas sobre los menores y personas con discapacidad","En sustitución de las penas por agresión sexual","Solo si no se ha cometido agresión sexual","En su mitad inferior si hay agresión sexual"], e:"Art. 188.5: «Las penas señaladas se impondrán en sus respectivos casos sin perjuicio de las que correspondan por las infracciones contra la libertad o indemnidad sexual cometidas…».", a:"Art. 188.5 CP", f:"Texto legal"},

  // --- ART. 189: CORRUPCIÓN DE MENORES ---
  {id:"T13-084", p:"Según el artículo 189.1 CP, quien capte o utilice a menores de edad o a personas con discapacidad necesitadas de especial protección con fines o en espectáculos exhibicionistas o pornográficos, o para elaborar material pornográfico, será castigado con:", o:["Prisión de uno a cinco años","Prisión de cinco a nueve años","Prisión de seis meses a dos años","Prisión de dos a seis años"], e:"Art. 189.1: pena de prisión de uno a cinco años, aplicable también a quien produzca, venda, distribuya, exhiba, ofrezca o facilite ese material o lo posea para esos fines.", a:"Art. 189.1 CP", f:"Texto legal"},
  {id:"T13-085", p:"Según el artículo 189.2 CP, las conductas del apartado 1 se castigan con prisión de cinco a nueve años cuando concurra, entre otras, la circunstancia de:", o:["Que se utilice a menores de dieciséis años","Que el material se difunda por internet","Que el autor sea mayor de edad","Que el material se haya elaborado en el extranjero"], e:"Art. 189.2: prisión de cinco a nueve años, entre otros casos, cuando se utilice a menores de dieciséis años, cuando el material sea de notoria importancia, cuando el culpable pertenezca a una organización o cuando concurra la agravante de reincidencia.", a:"Art. 189.2 CP", f:"Texto legal"},
  {id:"T13-086", p:"Según el artículo 189.4 CP, quien asista a sabiendas a espectáculos exhibicionistas o pornográficos en los que participen menores de edad o personas con discapacidad necesitadas de especial protección será castigado con:", o:["Prisión de seis meses a dos años","Prisión de tres meses a un año o multa de seis meses a dos años","Prisión de uno a cinco años","Multa de seis a doce meses"], e:"Art. 189.4: pena de seis meses a dos años de prisión.", a:"Art. 189.4 CP", f:"Texto legal"},
  {id:"T13-087", p:"Según el artículo 189.5 CP, quien para su propio uso adquiera o posea material pornográfico infantil será castigado con:", o:["Prisión de tres meses a un año o multa de seis meses a dos años","Prisión de uno a cinco años","Prisión de seis meses a dos años","Prisión de tres a seis meses o multa de seis a doce meses"], e:"Art. 189.5: pena de tres meses a un año de prisión o multa de seis meses a dos años. La misma pena se impone a quien acceda a sabiendas a ese material por medio de las tecnologías de la información y la comunicación.", a:"Art. 189.5 CP", f:"Texto legal"},
  {id:"T13-088", p:"Según el artículo 189.6 CP, quien tenga bajo su potestad, tutela, guarda o acogimiento a un menor y, conociendo su estado de prostitución o corrupción, no haga lo posible para impedir su continuación ni acuda a la autoridad, será castigado con:", o:["Prisión de tres a seis meses o multa de seis a doce meses","Prisión de seis meses a dos años","Prisión de uno a cinco años","Solo con la privación de la patria potestad"], e:"Art. 189.6: prisión de tres a seis meses o multa de seis a doce meses. Según el 189.7, el Ministerio Fiscal promoverá las acciones para privarle de la patria potestad, tutela, guarda o acogimiento.", a:"Art. 189.6 y 7 CP", f:"Texto legal"},
  {id:"T13-089", p:"Según el artículo 189.8 CP, ¿quién ordena las medidas para retirar o bloquear las páginas web que contengan o difundan pornografía infantil?", o:["Los jueces y tribunales, pudiendo acordarse con carácter cautelar a petición del Ministerio Fiscal","La Policía Judicial, de oficio","El Ministerio del Interior, por resolución administrativa","La Agencia Española de Protección de Datos"], e:"Art. 189.8: los jueces y tribunales ordenarán la retirada de esas páginas o aplicaciones o el bloqueo de su acceso. Estas medidas pueden acordarse con carácter cautelar a petición del Ministerio Fiscal.", a:"Art. 189.8 CP", f:"Texto legal"},

  // --- ARTS. 189 BIS Y 189 TER ---
  {id:"T13-090", p:"Según el artículo 189 bis CP, la distribución o difusión pública por internet u otras tecnologías de contenidos destinados a promover, fomentar o incitar a la comisión de los delitos de los Capítulos II, IV y V del Título VIII se castiga con:", o:["Multa de seis a doce meses o prisión de uno a tres años","Prisión de seis meses a dos años","Prisión de uno a cinco años","Multa de doce a veinticuatro meses"], e:"Art. 189 bis: pena de multa de seis a doce meses o pena de prisión de uno a tres años. Las autoridades judiciales ordenarán la retirada, interrupción o bloqueo de esos contenidos.", a:"Art. 189 bis CP", f:"Texto legal"},
  {id:"T13-091", p:"Según el artículo 189 ter CP, si una persona jurídica es responsable de los delitos del Capítulo V y el delito de la persona física tiene prevista una pena de prisión de más de cinco años, se le impondrá:", o:["Multa del triple al quíntuple del beneficio obtenido","Multa del doble al cuádruple del beneficio obtenido","Multa del doble al triple del beneficio obtenido","Multa de seis meses a dos años"], e:"Art. 189 ter: a) triple al quíntuple si la pena de prisión de la persona física es de más de cinco años; b) doble al cuádruple si es de más de dos años; c) doble al triple en el resto. Además puede acordarse la disolución (art. 33.7.b).", a:"Art. 189 ter CP", f:"Texto legal"},

  // --- DISPOSICIONES COMUNES (ARTS. 190 A 194 BIS) ---
  {id:"T13-092", p:"Según el artículo 190 CP, la condena de un juez o tribunal extranjero por delitos del Título VIII:", o:["Se equipara a las sentencias de los tribunales españoles a efectos de la agravante de reincidencia","No produce efectos en España","Solo produce efectos si hay tratado de extradición","Se equipara solo a efectos de la responsabilidad civil"], e:"Art. 190: la condena de un juez o tribunal extranjero por estos delitos se equipara a las sentencias españolas a efectos de aplicar la agravante de reincidencia.", a:"Art. 190 CP", f:"Texto legal"},
  {id:"T13-093", p:"Según el artículo 191.1 CP, para proceder por los delitos de agresiones sexuales y acoso sexual será precisa:", o:["Denuncia de la persona agraviada, de su representante legal o querella del Ministerio Fiscal; si la víctima es menor, persona con discapacidad necesitada de especial protección o desvalida, basta la denuncia del Ministerio Fiscal","Denuncia de la persona agraviada en todo caso","Querella de la persona agraviada","Nada, porque son delitos perseguibles de oficio sin requisito alguno"], e:"Art. 191.1: es precisa la denuncia de la persona agraviada, de su representante legal o la querella del Ministerio Fiscal, que actuará ponderando los intereses en presencia. Si la víctima es menor, persona con discapacidad necesitada de especial protección o desvalida, basta la denuncia del Ministerio Fiscal.", a:"Art. 191.1 CP", f:"Texto legal"},
  {id:"T13-094", p:"Según el artículo 191.2 CP, en los delitos de agresiones sexuales y acoso sexual, el perdón del ofendido o de su representante legal:", o:["No extingue la acción penal ni la responsabilidad de esa clase","Extingue la acción penal si se otorga antes del juicio","Extingue la responsabilidad penal en todo caso","Solo extingue la responsabilidad civil"], e:"Art. 191.2: «En estos delitos el perdón del ofendido o del representante legal no extingue la acción penal ni la responsabilidad de esa clase».", a:"Art. 191.2 CP", f:"Texto legal"},
  {id:"T13-095", p:"Según el artículo 192.1 CP, a los condenados a pena de prisión por delitos del Título VIII se les impondrá la medida de libertad vigilada, que se ejecutará después de la pena de prisión. ¿Cuál es su duración?", o:["De cinco a diez años si algún delito es grave, y de uno a cinco años si son menos graves","De uno a cinco años en todo caso","De dos a veinte años","De cinco a veinte años si el delito es grave"], e:"Art. 192.1: de cinco a diez años si alguno de los delitos es grave, y de uno a cinco años si son menos graves. Si es un solo delito menos grave cometido por un delincuente primario, el tribunal puede imponerla o no.", a:"Art. 192.1 CP", f:"Texto legal"},
  {id:"T13-096", p:"Según el artículo 192.2 CP, los ascendientes, tutores, curadores, guardadores, maestros o encargados de hecho o de derecho del menor que intervengan como autores o cómplices en delitos del Título VIII serán castigados con:", o:["La pena que les corresponda, en su mitad superior","La pena superior en grado","La pena que les corresponda más inhabilitación absoluta","La pena en su mitad inferior si son cómplices"], e:"Art. 192.2: «…serán castigados con la pena que les corresponda, en su mitad superior». No se aplica cuando esa circunstancia ya está prevista en el tipo penal.", a:"Art. 192.2 CP", f:"Texto legal"},
  {id:"T13-097", p:"Según el artículo 192.3 CP, en los delitos de los Capítulos I o V con víctima menor de edad, y en todo caso en los del Capítulo II, la autoridad judicial impondrá la privación de la patria potestad o la inhabilitación especial para ejercerla, por tiempo de:", o:["Cuatro a diez años","Seis meses a seis años","Dos a veinte años","Uno a cinco años"], e:"Art. 192.3: privación de la patria potestad o inhabilitación especial para la patria potestad, tutela, curatela, guarda o acogimiento por tiempo de cuatro a diez años. En el resto de delitos del Título puede imponerse razonadamente de seis meses a seis años.", a:"Art. 192.3 CP", f:"Texto legal"},
  {id:"T13-098", p:"Según el artículo 192.3 CP, la inhabilitación especial para profesiones u oficios que impliquen contacto regular y directo con menores se impondrá, si el delito es grave, por un tiempo superior al de la pena de prisión de entre:", o:["Cinco y veinte años","Dos y veinte años","Uno y diez años","Cuatro y diez años"], e:"Art. 192.3: superior entre cinco y veinte años al de la pena de prisión si el delito es grave, y entre dos y veinte años si es menos grave.", a:"Art. 192.3 CP", f:"Texto legal"},
  {id:"T13-099", p:"Según el artículo 194 CP, en los delitos de los Capítulos IV y V del Título VIII, cuando se hayan utilizado establecimientos o locales, abiertos o no al público:", o:["Se decretará en la sentencia su clausura definitiva, que puede adoptarse también con carácter cautelar","Se impondrá una multa al titular del local","Se decretará la clausura temporal por un máximo de cinco años","Se comunicará al Ayuntamiento para que retire la licencia"], e:"Art. 194: se decretará en la sentencia condenatoria la clausura definitiva del establecimiento o local. La clausura podrá adoptarse también con carácter cautelar.", a:"Art. 194 CP", f:"Texto legal"},
  {id:"T13-100", p:"Según el artículo 193 CP, en las sentencias condenatorias por delitos contra la libertad sexual, además del pronunciamiento sobre la responsabilidad civil, se harán en su caso los que procedan en orden a:", o:["La filiación y la fijación de alimentos","La adopción y el acogimiento","La custodia y el régimen de visitas","La pensión compensatoria"], e:"Art. 193: «…se harán, en su caso, los que procedan en orden a la filiación y fijación de alimentos». El art. 194 bis añade que las penas del Título se imponen sin perjuicio de las que correspondan por los actos de violencia física o psíquica.", a:"Art. 193 CP", f:"Texto legal"}
];
